import{_ as n,o as h,c as a,a4 as o}from"./chunks/framework.CRKgIIuH.js";const u=JSON.parse('{"title":"Nhập môn và cách học","description":"","frontmatter":{},"headers":[],"relativePath":"course/module-0-intro/index.md","filePath":"course/module-0-intro/index.md"}'),c={name:"course/module-0-intro/index.md"};function i(r,t,s,d,e,p){return h(),a("div",null,[...t[0]||(t[0]=[o(`<h1 id="nhap-mon-va-cach-hoc" tabindex="-1">Nhập môn và cách học <a class="header-anchor" href="#nhap-mon-va-cach-hoc" aria-label="Permalink to &quot;Nhập môn và cách học&quot;">​</a></h1><p><strong>Mục tiêu duy nhất của phần này:</strong> sau khi học xong, bạn nắm được <strong>workflow quản lý dữ liệu từ thiết kế đề cương đến kết thúc nghiên cứu</strong> và trả lời được “ở bước này phải làm gì, vì sao, và làm sai thì hậu quả gì”.</p><p><strong>Đối tượng:</strong> sinh viên BME, bác sĩ và nghiên cứu viên mới bắt đầu. Không cần biết lập trình. <strong>Thời lượng:</strong> khoảng 2–3 phút đọc mỗi bài + quiz (tổng khoảng 1 giờ), 6 bài. <strong>Nguồn:</strong> tổng hợp từ bản <em>Tổng hợp literature review — RDM Y Sinh</em> (20/11/2026). Có 103 mục tham khảo, trong đó một số đang chờ kiểm chứng (xem Roadmap). <strong>Phạm vi:</strong> chỉ lý thuyết và quiz. Lab, video, dữ liệu mẫu và chứng nhận sẽ bổ sung sau.</p><hr><h2 id="workflow-tong-the-—-7-giai-đoan-can-nho" tabindex="-1">Workflow tổng thể — 7 giai đoạn cần nhớ <a class="header-anchor" href="#workflow-tong-the-—-7-giai-đoan-can-nho" aria-label="Permalink to &quot;Workflow tổng thể — 7 giai đoạn cần nhớ&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. Thiết kế &amp; DMP → 2. Thu thập → 3. Làm sạch &amp; kiểm tra</span></span>
<span class="line"><span>→ 4. Chuẩn hóa (CDISC / FHIR / OMOP) → 5. Bảo mật &amp; khử định danh</span></span>
<span class="line"><span>→ 6. FAIR &amp; AI-ready → 7. Kết thúc: lưu trữ / hủy an toàn</span></span></code></pre></div><p>Quy tắc xuyên suốt: <strong>quyết định càng sớm càng rẻ</strong>. Một trường dữ liệu không định nghĩa ở bước 1 sẽ thành dữ liệu khuyết, không so sánh được, hoặc không dùng được cho AI ở bước 5–7. DMP không phải thủ tục hành chính — nó là bản hợp đồng về dữ liệu của cả nghiên cứu.</p><p><strong>Lớp kiểm soát xuyên suốt:</strong> bảo mật, đạo đức và pháp lý áp dụng ở mọi giai đoạn của vòng đời dữ liệu, từ lập kế hoạch đến lưu trữ hoặc tiêu hủy; đây không phải một bước chỉ làm ở cuối.</p><table tabindex="0"><thead><tr><th>7 bước của khóa học</th><th>6 giai đoạn trong review §2.1</th></tr></thead><tbody><tr><td>Thiết kế &amp; DMP</td><td>Lập kế hoạch</td></tr><tr><td>Thu thập</td><td>Thu thập</td></tr><tr><td>Làm sạch &amp; kiểm tra</td><td>Xử lý và chuẩn hóa</td></tr><tr><td>Chuẩn hóa</td><td>Xử lý và chuẩn hóa</td></tr><tr><td>Phân tích</td><td>Bước 3–4: làm sạch, kiểm tra và chuẩn hóa để phân tích</td></tr><tr><td>Bảo mật &amp; khử định danh</td><td>Áp dụng xuyên suốt</td></tr><tr><td>FAIR &amp; AI-ready</td><td>Chia sẻ, công bố và tái sử dụng</td></tr><tr><td>Kết thúc: lưu trữ / hủy an toàn</td><td>Lưu trữ dài hạn hoặc tiêu hủy</td></tr></tbody></table><hr>`,10)])])}const l=n(c,[["render",i]]);export{u as __pageData,l as default};
